    lower_name := lower(name)
    exact := password_exact[_]
    lower_name == exact
} else {
    lower_name := lower(name)
    suffix := password_suffixes[_]
    endswith(lower_name, suffix)
    not startswith(lower_name, "cache_")
    not contains(lower_name, "_cache_")
}

is_empty_value(value) {
    value.ir_type == "String"
    count(trim_space(value.value)) == 0
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

check_hash_value(hash_val) {
    hash_val.ir_type == "Hash"
    hash_val.value[k]
    is_password_field(k)
    is_empty_value(hash_val.value[k])
} else {
    hash_val.ir_type == "Assign"
    hash_val.left.ir_type == "String"
    is_password_field(hash_val.left.value)
    is_empty_value(hash_val.right)
} else {
    false
}

check_nested_empty(value) = found {
    found := {v |
        walk(value, [_, node])
        node.ir_type == "Hash"
        node.value[k]
        is_password_field(k)
        is_empty_value(node.value[k])
        v := node.value[k]
    } | {v |
        walk(value, [_, node])
        node.ir_type == "Assign"
        node.left.ir_type == "String"
        is_password_field(node.left.value)
        is_empty_value(node.right)
        v := node.right
    }
}

all_keyvalues(node) = kvs {
